		: _stream(stream) {}

	void operator&(auto&& arg) {
		_stream << arg;
	}

	template<typename ...Ts>
	void operator()(Ts&&... args) {
		(_stream << ... << args);
	}

	template<typename ...Ts>
	void forward(Ts&&... args) {
		_stream.put(std::forward<Ts>(args)...);
	}
};

