DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    // Create a mutable copy of the buffer since buffer_adaptor requires non-const reference
    std::vector<uint8_t> mutable_buffer(buffer.begin(), buffer.end());

    // Create buffer_adaptor
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(mutable_buffer);

    // Preview the first byte (data_type) without advancing the read pointer
    uint8_t previewed_data_type = 0;
    if (adaptor.size() >= sizeof(uint8_t)) {
        adaptor.copy(&previewed_data_type, sizeof(uint8_t));
    }

    // Check available data size - minimum is header (1 byte type + 4 bytes count)
    if (adaptor.size() < sizeof(uint8_t) + sizeof(uint32_t)) {
        return result;
    }

    // Create binary_stream for reading
    hexi::binary_stream stream(adaptor);

    // Read data_type
    stream >> result.data_type;

    // Read item_count
    uint32_t item_count = 0;
    stream >> item_count;

    // Check if stream is still good
    if (!stream.good()) {
        return result;
    }

    // Read items based on data_type
    if (result.data_type == 0) {
        // Type 0: read integers (uint32_t)
        result.int_items.reserve(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            uint32_t value = 0;
            stream >> value;
            if (!stream.good()) {
                break;
            }
            result.int_items.push_back(value);
        }
    } else if (result.data_type == 1) {
        // Type 1: read floats
        result.float_items.reserve(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            float value = 0.0f;
            stream >> value;
            if (!stream.good()) {
                break;
            }
            result.float_items.push_back(value);
        }
    }

    return result;
}
