bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create buffer adaptor with init_empty to start writing from the beginning
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Calculate required space
    // - header: 4 bytes (uint32_t)
    // - items count prefix: 4 bytes (uint32_t for prefixed container)
    // - items data: items.size() * 4 bytes
    const std::size_t required_space = sizeof(uint32_t) + 
                                       sizeof(uint32_t) + 
                                       items.size() * sizeof(uint32_t);

    // Check available space
    if (adaptor.free() < required_space) {
        return false; // Insufficient space
    }

    // Get write pointer (as required by specification)
    [[maybe_unused]] auto write_ptr = adaptor.write_ptr();

    // Create binary stream and write container data
    hexi::binary_stream stream(adaptor);

    // Write header
    stream << header;

    // Write items using prefixed adaptor (writes count prefix + elements)
    stream << hexi::prefixed(items);

    // Return true if write was successful, false otherwise
    return stream.good();
}
