#pragma once

#include <hexi/pmc/buffer.h>
#include <hexi/shared.h>
#include <hexi/allocators/default_allocator.h>
#include <hexi/detail/intrusive_storage.h>
#include <concepts>
#include <functional>
#include <memory>
#include <utility>
#ifdef HEXI_BUFFER_DEBUG
#include <algorithm>
#include <vector>
#endif
#include <cstddef>
#include <cstdint>
