struct ref_counting : no_ref_counting {};

template<typename _ty,
	std::size_t _elements,
	std::derived_from<no_ref_counting> ref_count_policy = no_ref_counting,
	std::derived_from<safe_entrant> entrant_policy = safe_entrant
