	 * @brief Clear the container.
	 * 
	 * Resets the read and write offsets, does not explicitly
	 * erase the data contained within the buffer but should
	 * be treated as such.
	 */
	void clear() {
		read_offset = 0;
		write_offset = 0;
	}

