	void read(void* destination, size_type length) {
		if(error_) {
			return;
		}

		if(std::fseek(file_, read_, 0)) {
			error_ = true;
			return;
		}

		if(std::fread(destination, length, 1, file_) != 1) {
			error_ = true;
			return;
		}

		read_ += length;
	}

	/**
