	 * of the buffer.
	 * 
	 * @note The underlying buffer will not be cleared but should be treated
	 * as thought it has been.
	 */
	void clear() {
		read_ = 0;

		if constexpr(has_clear<buf_type>) {
			buffer_.clear();
		}
	}
