    const char* dst_begin = static_cast<const char*>(dst);
    const char* dst_end = dst_begin + dst_len;

    // Two regions overlap if:
    // - src starts within dst's range, OR
    // - dst starts within src's range
    return boost::pointer_in_range(src_begin, dst_begin, dst_end) ||
           boost::pointer_in_range(dst_begin, src_begin, src_end);
}

bool safe_memory_copy(void* destination, const void* source, std::size_t length) {
    // Check for overlap first
    if (check_regions_overlap(source, length, destination, length)) {
        return false; // Overlap detected, unsafe to copy with memcpy
    }

    // Safe to copy - no overlap
    std::memcpy(destination, source, length);
    return true;
}

