[[maybe_unused]] constexpr static allow_throw_t allow_throw {};

struct init_empty_t {};
constexpr static init_empty_t init_empty {};

#define STRING_ADAPTOR(adaptor_name)                      \
template<typename string_type>                            \
struct adaptor_name {                                     \
    string_type& str;                                     \
    string_type* operator->() { return &str; }            \
};                                                        \
