		while(head != &root_) {
			const auto buffer = buffer_from_node(head);
			const auto data = buffer->read_data();

			for(const auto& byte : data) {
				if(byte == value) {
					return index;
				}

				++index;
			}

			head = head->next;
		}

		return npos;
	}

	/**
	 * @brief Retrieves the container's allocator.
	 * 
	 * @return The memory allocator.
	 */
	auto& get_allocator() {
		return allocator_;
	}

	/**
	 * @brief Retrieves the container's allocator.
	 * 
	 * @return The memory allocator.
	 */
	auto& get_allocator() const {
		return allocator_;
	}

