#include <hexi/binary_stream.h>
#include <hexi/buffer_adaptor.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>
#include <span>
#include <string_view>
#include <bit>

struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly
        adaptor & sensor_id;

        // Write number of temperatures
        uint32_t temp_count = static_cast<uint32_t>(temperatures.size());
        adaptor & temp_count;

        // Convert each temperature from native to little-endian using conditional_reverse
        // with runtime parameters, then write using the stream's write method (via forward)
        for (const auto& temp : temperatures) {
            auto converted = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.forward(converted);
        }

        // Convert pressure from native to little-endian using conditional_reverse
        // with runtime parameters, then write using the stream's write method (via forward)
        auto converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.forward(converted_pressure);
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor & sensor_id;

        // Read number of temperatures
        uint32_t temp_count;
        adaptor & temp_count;

        // Read each temperature, then convert from little-endian to native using little_to_native_inplace
        temperatures.resize(temp_count);
        for (auto& temp : temperatures) {
            adaptor.forward(temp);
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure, then convert from little-endian to native using little_to_native_inplace
        adaptor.forward(pressure);
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer, hexi::init_empty);
    hexi::binary_stream stream(adaptor);
    stream.serialise(data);
    return buffer;
}

MeasurementData deserialize_measurement_data(const std::span<const uint8_t> buffer) {
    std::span<uint8_t> mutable_view(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::buffer_adaptor adaptor(mutable_view);
    hexi::binary_stream stream(adaptor);
    MeasurementData data;
    stream.deserialise(data);
    return data;
}

struct SensorInfo {
    uint32_t sensor_id;
    std::string_view sensor_name;
};

SensorInfo extract_sensor_info(const std::span<const uint8_t> buffer) {
    std::span<uint8_t> mutable_view(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::buffer_adaptor adaptor(mutable_view);
    hexi::binary_stream stream(adaptor);

    SensorInfo info;

    // Use view to extract null-terminated sensor name string
    info.sensor_name = stream.view();

    // Read sensor_id (enforce_read_bounds is called automatically by the stream)
    stream >> info.sensor_id;

    // Skip remaining data using skip
    auto remaining = stream.size();
    if (remaining > 0 && stream.good()) {
        stream.skip(remaining);
    }

    return info;
}
